// --- Popup Integration & Form Detection Message Bridge ---
(function() {
  const browserApi = globalThis.browser?.runtime?.id ? globalThis.browser : globalThis.chrome;
  if (!browserApi?.runtime?.onMessage) return;

  let isDetectionDisabled = false;
  if (browserApi?.storage?.local) {
    browserApi.storage.local.get(['form_detection_enabled'], (res) => {
      isDetectionDisabled = (res?.form_detection_enabled === false);
      window.__nextoffer_detection_disabled = isDetectionDisabled;
    });
    browserApi.storage.onChanged?.addListener((changes, area) => {
      if (area === 'local' && 'form_detection_enabled' in changes) {
        isDetectionDisabled = (changes.form_detection_enabled.newValue === false);
        window.__nextoffer_detection_disabled = isDetectionDisabled;
      }
    });
  }

  browserApi.runtime.onMessage.addListener((msg, sender, sendResponse) => {
    if (msg.type === 'SET_DETECTION_ENABLED') {
      isDetectionDisabled = !msg.enabled;
      window.__nextoffer_detection_disabled = isDetectionDisabled;
      sendResponse({ ok: true, disabled: isDetectionDisabled });
      return true;
    }

    if (msg.type === 'POPUP_GET_STATUS') {
      if (isDetectionDisabled || window.__nextoffer_detection_disabled) {
        sendResponse({
          ok: true,
          disabled: true,
          title: document.title || '',
          url: location.href,
          fieldCount: 0,
          isApplicationPage: false,
          status: window.__nextoffer_fill_status || 'idle',
          logs: window.__nextoffer_fill_logs || []
        });
        return true;
      }

      let fieldCount = 0;
      let isAppPage = false;
      try {
        if (typeof window.__nextoffer_scan === 'function') {
          let scan = window.__nextoffer_scan();
          fieldCount = scan.fieldCount || 0;
          isAppPage = scan.isApplicationPage || false;
        }
      } catch(e) {
        console.warn('[Content] Scan error:', e);
      }

      let logs = window.__nextoffer_fill_logs || [];
      let fillStatus = window.__nextoffer_fill_status || 'idle';

      sendResponse({
        ok: true,
        disabled: false,
        title: document.title || '',
        url: location.href,
        fieldCount: fieldCount,
        isApplicationPage: isAppPage,
        status: fillStatus,
        logs: logs
      });
      return true;
    }

    if (msg.type === 'POPUP_START_FILL') {
      window.__nextoffer_fill_logs = [];
      if (typeof window.__nextoffer_run_fill === 'function') {
        window.__nextoffer_run_fill(msg.resumeId).then(res => {
          sendResponse(res);
        }).catch(err => {
          sendResponse({ ok: false, error: err?.message || String(err) });
        });
        return true; // async
      } else {
        sendResponse({ ok: false, error: '填表引擎未初始化，请刷新页面' });
        return true;
      }
    }

    if (msg.type === 'POPUP_ABORT_FILL') {
      if (window.__nextoffer_abort_controller) {
        window.__nextoffer_abort_controller.abort();
      }
      if (typeof $n === 'function') {
        $n();
      }
      window.__nextoffer_fill_status = 'idle';
      window.__nextoffer_is_filling = false;
      sendResponse({ ok: true });
      return true;
    }

    if (msg.type === 'POPUP_GET_JOB_INFO') {
      let title = document.title || '';
      let company = '';
      if (title.includes('-')) company = title.split('-')[0].trim();
      else if (title.includes('—')) company = title.split('—')[0].trim();
      else if (title.includes(' ')) company = title.split(' ')[0].trim();
      if (!company || company.length > 25) company = location.hostname.replace(/^www\./, '').split('.')[0];
      let position = '';
      if (title.includes('-') && title.split('-').length > 1) {
        position = title.split('-')[1].trim();
      } else {
        position = '网申岗位';
      }
      sendResponse({ ok: true, company: company, position: position, url: location.href });
      return true;
    }
  });
})();
